import sys, random
sys.path.insert(0,'/workspace/submission')
from treap import Priors, fat_insert, fat_pop, fat_pairs

def real(n):
    return 0 if n is None else 1+real(n[3])+real(n[4])
def dump(n, d, out):
    if n is None: return
    dump(n[3], d+1, out)
    out.append('  '*d + f'k={n[0]} sz={n[5]} real={real(n)}')
    dump(n[4], d+1, out)

def brute_check(n=200, seed=0, trace=False):
    rng = random.Random(seed)
    pr = Priors(); root=None; model={}; ver=0
    for step in range(n):
        op = rng.random()
        if op < 0.55 or not model:
            key = (rng.randint(0,5), step)
            if key in model: continue
            root = fat_insert(root, key, ('r',key), pr.take(), ver)
            model[key] = 0
        else:
            key = rng.choice(list(model))
            thr = key[0] if rng.random() < 0.8 else None
            if trace:
                out=[]; dump(root,0,out); print('before pop', key, 'thr', thr); print('\n'.join(out))
            root, lag, cnt = fat_pop(root, key, thr, ver, 0)
            elag = model.pop(key)
            if thr is not None:
                ecnt = sum(1 for k in model if k[0] < thr)
                for k in list(model):
                    if k[0] < thr: model[k] += 1
            else:
                ecnt = 0
            if trace:
                out=[]; dump(root,0,out); print('after: got cnt',cnt,'exp',ecnt); print('\n'.join(out))
            assert lag == elag, (step,'lag',lag,elag)
            if cnt != ecnt:
                print('CNT MISMATCH step',step,'key',key,'thr',thr,'got',cnt,'exp',ecnt)
                out=[]; dump(root,0,out); print('\n'.join(out))
                return False
            pairs=[]; fat_pairs(root,0,pairs)
            got={}
            for p,l in pairs: got[p[1]]=l
            assert got == model, (step,'pairs',got,model)
    return True

for s in range(30):
    if not brute_check(150, s):
        break
